export const BODY: string = "\n<p>لديك صورة ونموذج يرفض كل ما يزن أكثر من 50 كيلوبايت. الحل ليس في التخمين، بل في خطوات مرتبة توصلك إلى الهدف من أول مرة.</p>\n<p>سيرافقك هذا الدليل في العملية كاملة. ستجهّز ملف المصدر المناسب، وتمرره عبر الأداة، وتراجع النتيجة، وترفعها بثقة.</p>\n<p>لا تحتاج إلى تثبيت أي برنامج. كل ما يلي يعمل في متصفح عادي، على الهاتف أو الحاسوب، دون حساب أو اشتراك.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: جهّز ملف المصدر الصحيح</h2>\n<p>ابدأ دائمًا من الصورة الأصلية بأعلى جودة لديك. النسخة الأصلية من الكاميرا تحمل تفاصيل أكثر بكثير من نسخة أُعيد حفظها أو لقطة شاشة.</p>\n<p>تحقق من قواعد البوابة قبل أن تبدأ: الحد الأقصى للحجم، والصيغة المقبولة، والأبعاد المطلوبة بالبكسل. هذه التفاصيل الثلاثة تحدد كل خطوة لاحقة.</p>\n<h2 id=\"step-1-open-the-tool\">الخطوة 1: افتح ضاغط 50 كيلوبايت</h2>\n<p>افتح <a href=\"/ar/daght-as-sura-ila-50kb/\">ضاغط 50 كيلوبايت</a> في متصفحك. تفتح الأداة فورًا دون تثبيت، وتعمل بالكامل على جهازك.</p>\n<p>لا تُرفع صورتك إلى أي خادم. هذه النقطة مهمة خصوصًا مع صور الهوية وجواز السفر، حيث تبقى بياناتك على جهازك طوال الوقت.</p>\n<h2 id=\"step-2-upload\">الخطوة 2: ارفع صورتك</h2>\n<p>أسقط صورتك في منطقة الرفع أو انقر لاختيارها من جهازك. تُقبل ملفات JPG وPNG وWebP وHEIC، بحجم إدخال يصل إلى 25 ميغابايت.</p>\n<p>إذا كانت صورتك لقطة شاشة، فابحث عن الملف الأصلي بدلها. لقطات الشاشة تحمل ضجيجًا يهدر كيلوبايتات ثمينة ويجعل الوصول إلى الهدف أصعب.</p>\n<h2 id=\"step-3-let-it-search\">الخطوة 3: دع الأداة تجد أفضل جودة</h2>\n<p>تعمل الأداة تلقائيًا. تُجري بحثًا ثنائيًا عن الجودة، فتختبر مستويات مختلفة حتى تجد الأعلى الذي ما زال يناسب حد 50 كيلوبايت.</p>\n<p>لا حاجة إلى تخمين رقم الجودة بنفسك. قد تكون أفضل جودة لصورتك 63 بالمئة لا رقمًا مستديرًا مثل 50 أو 70، والبحث يجد تلك النقطة بدقة.</p>\n<h2 id=\"step-4-preview\">الخطوة 4: عاين قبل التنزيل</h2>\n<p>قبل التنزيل، كبّر الصورة وافحص الوجه أو النص عن قرب. تأكد من أن التفاصيل المهمة ما زالت واضحة ولم تتحول إلى بقعة ضبابية.</p>\n<p>ابحث عن شارة «أقل من 50 كيلوبايت» في النتيجة. هذه الشارة تؤكد أن الملف النهائي أقل من الحد بالبايتات، فلا تعتمد على قراءة جهازك التقريبية.</p>\n<h2 id=\"step-5-download\">الخطوة 5: نزّل الملف وسمِّه بوضوح</h2>\n<p>نزّل الملف وسمِّه باسم واضح يصف الغرض، مثل sora-jawaz-50kb.jpg. الاسم الواضح يجنّبك الخلط عندما تحتاج الملف نفسه بعد أشهر.</p>\n<p>احتفظ بالملف الأصلي في مكان منفصل. قد تغيّر البوابة قواعدها، وملف 50 كيلوبايت لا يمكن إعادته إلى جودة الأصل.</p>\n<h2 id=\"fixing-a-missed-target\">كيف تصلح المشكلة عند عدم الوصول إلى الهدف</h2>\n<p>إذا ظهر تحذير «لم يتحقق الهدف»، فالمشكلة في الإعدادات لا في الصورة. غيّر الصيغة أولًا إلى JPG أو WebP، لأن PNG نادرًا ما يصل إلى 50 كيلوبايت مع الصور الفوتوغرافية.</p>\n<p>إذا لم يكفِ ذلك، اسمح بتقليص الأبعاد أو قصّ الصورة بإحكام أكبر. كل بكسل تزيله يحرّر مساحة من ميزانية 50 كيلوبايت.</p>\n<h2 id=\"passport-photo-tips\">نصائح لصور جواز السفر والهوية</h2>\n<p>لصور جواز السفر، التقط صورة جديدة بخلفية فاتحة بسيطة وإضاءة نهارية من نافذة. الإضاءة الجيدة تفعل للجودة أكثر من أي إعداد في الأداة.</p>\n<p>اجعل الوجه مواجهًا للأمام واملأ به معظم الإطار. كلما كان الوجه أكبر في الصورة، حصل على حصة أكبر من ميزانية 50 كيلوبايت.</p>\n<h2 id=\"signature-scan-tips\">نصائح للتوقيعات والمستندات الممسوحة ضوئيًا</h2>\n<p>التوقيع الممسوح ضوئيًا سهل الضغط لأنه معظمه مساحة بيضاء. امسحه بدقة معتدلة واحفظه بصيغة JPG لتسهيل الوصول إلى 50 كيلوبايت.</p>\n<p>إذا كان المستند نصًا، فاحرص على بقاء الحروف واضحة. قلّل الأبعاد تدريجيًا بدل خفض الجودة بقوة، لأن النص يتحسس من فقدان الحدة أكثر من الصور.</p>\n<h2 id=\"phone-workflow\">كيف تنجز كل شيء على الهاتف</h2>\n<p>كل الخطوات تعمل على الهاتف. افتح الأداة في المتصفح وارفع الصورة من معرضك مباشرة، دون الحاجة إلى نقلها إلى حاسوب.</p>\n<p>عاين النتيجة على شاشة الهاتف بالتكبير بإصبعيك. إذا بدا الوجه واضحًا في التكبير، فالملف جاهز للرفع إلى البوابة.</p>\n<h2 id=\"checking-your-result\">كيف تراجع نتيجتك كما يجب</h2>\n<p>افتح الملف المنزّل مرة واحدة قبل رفعه. تأكد من أن الوجه واضح وأن النص مقروء وأن الملف يفتح دون مشاكل.</p>\n<p>تحقق من حجم الملف بالبايتات لا بالتقريب. البوابات تفحص العدد الدقيق، وملف 49 كيلوبايت يجتاز بينما ملف 51 كيلوبايت يُرفض.</p>\n<h2 id=\"choosing-dimensions\">كيف تختار الأبعاد قبل الضغط</h2>\n<p>إذا طلبت البوابة أبعادًا ثابتة، فقصّ الصورة إلى تلك النسبة قبل الضغط. قص 600 في 600 ثم الضغط يعطي نتيجة أنظف من ضغط صورة عريضة والتمني.</p>\n<p>وإذا لم تكن الأبعاد مهمة، فاترك الأداة تقرر. خفض الجودة أولًا بالحجم الكامل يحافظ على تفاصيل أكثر من تقليص الأبعاد مبكرًا.</p>\n<h2 id=\"scanned-documents\">كيف تضغط المستندات الممسوحة إلى 50 كيلوبايت</h2>\n<p>المستندات الممسوحة ضوئيًا تُضغط جيدًا لأنها تحمل مساحات بيضاء واسعة. امسح بدقة 200 نقطة في البوصة أو أقل، فالدقة الأعلى تضيف وزنًا دون فائدة للبوابة.</p>\n<p>حوّل المسح إلى JPG قبل الضغط. صيغة PNG تحفظ النص حادًا لكنها تزن كثيرًا، بينما JPG توازن بين وضوح الحروف وحجم الملف.</p>\n<h2 id=\"heic-photos\">كيف تتعامل مع صور HEIC من آيفون</h2>\n<p>صور HEIC من آيفون صغيرة أصلًا، لكن كثيرًا من البوابات لا تقبلها. حوّل الصورة إلى JPG أولًا، ثم اضغط إلى 50 كيلوبايت.</p>\n<p>إذا حوّلت من تطبيق الصور في هاتفك، فاحفظ النسخة بأعلى جودة ثم اضغطها. التحويل بجودة منخفضة يضيع تفاصيل لا يمكن استعادتها.</p>\n<h2 id=\"batch-50kb\">كيف تضغط عدة ملفات إلى 50 كيلوبايت دفعة واحدة</h2>\n<p>لعدة ملفات، استخدم أداة الضغط الجماعي وحدد هدف 50 كيلوبايت لكل صورة. ترفع الدفعة مرة واحدة وتنزّلها كملف ZIP واحد.</p>\n<p>راجع كل صورة في الدفعة قبل الاعتماد عليها. صورة جماعية مزدحمة قد تفشل في الوصول إلى الهدف، بينما تنجح الصور الشخصية بسهولة.</p>\n<h2 id=\"verifying-before-submit\">قائمة أخيرة قبل الإرسال</h2>\n<p>قبل الإرسال، تأكد من ثلاثة أشياء: الحجم أقل من 50 كيلوبايت، والصيغة مقبولة، والأبعاد مطابقة لقواعد البوابة.</p>\n<p>احتفظ بنسخة من الملف المرفوع باسم واضح. قد تحتاجه مجددًا لبطاقة القبول أو لجولة أخرى من الطلب نفسه.</p>\n<h2 id=\"group-photos\">صور المجموعات والصور المزدحمة عند 50 كيلوبايت</h2>\n<p>صور المجموعات هي أصعب الحالات عند 50 كيلوبايت. كل وجه إضافي يستهلك حصة من الميزانية، فتتوزع الكيلوبايتات على وجوه كثيرة.</p>\n<p>إذا كان ممكنًا، قصّ الصورة على الأشخاص المهمين فقط. وإذا كان لا بد من الجماعة كاملة، فاقبل بعض النعومة أو اطلب من البوابة حدًا أكبر.</p>\n<h2 id=\"file-naming\">كيف تسمّي الملفات حتى لا تختلط عليك أبدًا</h2>\n<p>سمِّ الملفات حسب الغرض لا التاريخ. اسم مثل sora-jawaz-50kb.jpg مفيد بعد سنة، بينما اسم مثل IMG_4821.jpg لا يخبرك بشيء.</p>\n<p>أنشئ مجلدًا لكل طلب، وضع فيه الصورة والتوقيع معًا. التنظيم البسيط يمنع رفع الملف الخاطئ في اللحظة الأخيرة.</p>\n<h2 id=\"portal-previews\">كيف تستخدم معاينة البوابة للتحقق مرة أخرى</h2>\n<p>بعض البوابات تعرض معاينة لصورتك قبل الإرسال النهائي. استخدمها للتحقق من أن الوجه يظهر بالاتجاه الصحيح وأن الصورة لم تُقلب.</p>\n<p>إذا بدت المعاينة مقبولة، فأنت جاهز. وللشرح الكامل حول هذا الحد، اقرأ <a href=\"/ar/blog/dalil-daght-as-sura-ila-50kb/\">الدليل الكامل لضغط الصورة إلى 50 كيلوبايت</a>، وقارن الأحجام في <a href=\"/ar/blog/hajm-as-sura-50kb-vs-100kb-vs-200kb/\">50 كيلوبايت مقابل 100 كيلوبايت مقابل 200 كيلوبايت</a>، أو جرّب <a href=\"/ar/daght-as-sura-ila-100kb/\">ضاغط 100 كيلوبايت</a> إذا سمحت بوابتك بحد أكبر.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كم يستغرق ضغط صورة إلى 50 كيلوبايت؟","answer":"عادة أقل من دقيقة لصورة واحدة. البحث الثنائي عن الجودة يختبر عدة مستويات بسرعة، والوقت الأكبر يذهب إلى الرفع والتنزيل لا إلى الضغط نفسه."},{"question":"هل يمكنني ضغط عدة صور إلى 50 كيلوبايت دفعة واحدة؟","answer":"نعم، باستخدام أداة الضغط الجماعي يمكنك معالجة عدة صور دفعة واحدة، كل واحدة بهدف 50 كيلوبايت. راجع كل نتيجة قبل التنزيل، لأن بعض الصور المزدحمة قد لا تصل إلى الحد."},{"question":"لماذا يزن ملفي المنزّل 48 كيلوبايت بدل 50 كيلوبايت بالضبط؟","answer":"لأن 50 كيلوبايت حد أقصى لا هدف دقيق. الأداة تبحث عن أعلى جودة تناسب الحد، فإذا كانت أفضل جودة ممكنة تنتج 48 كيلوبايت، فهذا هو الملف الصحيح. أي ملف تحت الحد يجتاز البوابة."},{"question":"بوابتي تريد صورة أقل من 50 كيلوبايت وبأبعاد 600 في 600 بكسل. كيف أحقق الاثنين معًا؟","answer":"ابدأ بصورة عالية الجودة واقصّها إلى نسبة مربعة أولًا، ثم اضغط إلى 50 كيلوبايت. بعد الضغط تحقق من الأبعاد النهائية. وإذا غيّر الضغط الأبعاد، أعد الضبط مع تثبيت الأبعاد المطلوبة قبل الضغط."},{"question":"هل يجب تحويل HEIC إلى JPG قبل الضغط إلى 50 كيلوبايت؟","answer":"يُفضّل ذلك. صيغة HEIC تُضغط بكفاءة، لكن بعض البوابات ترفضها. حوّل إلى JPG أولًا لتتأكد من قبول الصيغة، ثم اضغط إلى 50 كيلوبايت."},{"question":"ماذا أفعل إذا استمرت البوابة في رفض ملفي الذي يزن 49 كيلوبايت؟","answer":"تحقق أولًا من الأبعاد المطلوبة، فقد يكون الرفض بسبب الأبعاد لا الحجم. ثم تأكد من الصيغة، لأن بعض البوابات ترفض WebP. وإذا كان كل شيء صحيحًا، أعد الضغط من الملف الأصلي لا من النسخة المضغوطة."}];
